import type { Insight, InsightBlock, InsightTopic } from '@/content/types';

/**
 * An insight is published once it has body blocks AND its publication date has
 * arrived. A future `datePublished` genuinely holds the piece back: it is left
 * out of the listing and the sitemap, and its route is marked `noindex` until
 * the date passes.
 *
 * That distinction matters. `datePublished` is emitted in BlogPosting schema
 * and read as a freshness signal, so the date has to be the date the article
 * actually became available — scheduling forward is honest, backdating is not.
 *
 * Evaluated in UTC to match the ISO dates in the content and the `dateModified`
 * emitted in schema, so a build machine's timezone cannot flip an article's
 * state a few hours early or late.
 */
export const isPublished = (i: Insight, now: Date = new Date()): boolean => {
  if ((i.body?.length ?? 0) === 0) return false;
  if (!i.datePublished) return true;
  return i.datePublished <= now.toISOString().slice(0, 10);
};

/**
 * True unless the href points at an insight that is not live yet.
 *
 * Cross-links are authored against the whole set, but a scheduled piece is
 * noindex and unlisted — linking to it from a live page would point internal
 * links at a page we are asking Google to ignore. Non-insight hrefs always
 * pass, so this can filter a mixed list of services, case studies and
 * articles without knowing which is which.
 */
export const isLinkLive = (href: string, now: Date = new Date()): boolean => {
  const match = /^\/insights\/([^/#?]+)/.exec(href);
  if (!match) return true;
  const target = insights.find((i) => i.id === match[1]);
  return target ? isPublished(target, now) : false;
};

/** Insights that are live: written, and past their publication date. */
export const publishedInsights = (now: Date = new Date()): Insight[] =>
  insights.filter((i) => isPublished(i, now));

/**
 * The number shown against an article in the UI.
 *
 * The authored `number` is a stable slot across the whole set, so once
 * scheduled or unwritten pieces are filtered out those slots read as gaps — a
 * listing of four articles numbered 01, 02, 03, 08. The displayed number is
 * therefore the position within the *published* set, falling back to the
 * authored slot for a piece that is not live yet (its own page, viewed direct).
 */
export const insightNumber = (id: string, now: Date = new Date()): string => {
  const position = publishedInsights(now).findIndex((i) => i.id === id);
  if (position >= 0) return String(position + 1).padStart(2, '0');
  return insights.find((i) => i.id === id)?.number ?? '01';
};

/**
 * Prose words in an article body.
 *
 * Code blocks are excluded on purpose: nobody reads a 30-line listing at
 * prose speed, and counting it would push a short argument with two listings
 * past a long one without. Headings, asides and captions do count — they are
 * read.
 */
function proseWords(blocks: InsightBlock[] = []): number {
  const text = blocks
    .map((b) => {
      if (typeof b === 'string') return b;
      if (b.type === 'heading' || b.type === 'aside') return b.text;
      if (b.type === 'image') return b.caption ?? '';
      return b.caption ?? '';
    })
    .join(' ');
  return text.split(/\s+/).filter(Boolean).length;
}

/**
 * Reading time in whole minutes, at 220 wpm, floored at 1.
 *
 * Derived rather than authored so it cannot drift away from the article when
 * a section is added, and so a stub never advertises a read time it has not
 * earned.
 */
export const insightReadMinutes = (insight: Insight): number =>
  Math.max(1, Math.round(proseWords(insight.body) / 220));

/**
 * "12 Sep 2026" — the byline date, short enough to sit on one line on a phone.
 *
 * Pinned to UTC so the card, the article byline and the JSON-LD date can never
 * disagree by a day depending on where the page is rendered.
 */
export const insightDate = (iso: string): string =>
  new Date(iso + "T00:00:00Z").toLocaleDateString("en-GB", {
    day: "numeric",
    month: "short",
    year: "numeric",
    timeZone: "UTC",
  });

/**
 * Topics that actually have a live article behind them, in the order they
 * first appear in the set. A filter pill that returns nothing is worse than
 * an absent pill, so the listing only ever offers these.
 */
export const insightTopics = (now: Date = new Date()): InsightTopic[] => {
  const seen: InsightTopic[] = [];
  for (const i of publishedInsights(now)) {
    if (i.topic && !seen.includes(i.topic)) seen.push(i.topic);
  }
  return seen;
};

/**
 * The piece the listing leads with: the most recently published one. Falls
 * back to the first live article on the (impossible in practice) chance that
 * nothing carries a date.
 */
export const featuredInsight = (now: Date = new Date()): Insight | undefined => {
  const live = publishedInsights(now);
  return (
    [...live].sort((a, b) => (b.datePublished ?? '').localeCompare(a.datePublished ?? ''))[0] ??
    live[0]
  );
};

export const insights: Insight[] = [{ id: 'angular-signals-state-management', cover: { src: '/media/insights/angular-signals-state-management/cover.webp', alt: 'Angular Signals state management architecture showing local state, computed values and UI updates.', width: 1730, height: 909, }, takeaways: ['Keep UI state local with Angular Signals when only one component needs it.', 'Promote state only when a second real consumer exists in the application.', 'Use a simple progression: component signal → service signals → application store.', 'Precise signal-based state makes zoneless Angular easier to reason about.',], topic: 'Architecture', seoTitle: 'Angular Signals State Management: When You Don’t Need NgRx', seoDescription: 'Learn when Angular Signals are enough for state management, when to move state into a service, and when shared application state actually needs NgRx or another store.', datePublished: '2026-09-12', number: '01', title: 'Angular Signals for State Management: Start Without a Store', dek: 'Most Angular UI state does not need a store. Start with a local signal, promote it when the application actually shares it, and introduce a store only when the architecture earns one.', related: [{ label: 'Angular development services', href: '/services/angular-development', }, { label: 'PRIMS Member Portal — where shared state earned a store', href: '/work/prims-member-portal', }, { label: 'Fiji Immigration internal system', href: '/work/fiji-immigration-internal', }, { label: 'Angular zoneless change detection migration', href: '/insights/angular-zoneless-change-detection', },], cta: 'Working with an Angular codebase where a simple UI change means touching multiple services, subscriptions and files? I can help identify where the state architecture can be simplified and which abstractions are actually worth keeping.', body: ['Most Angular UI state does not need a global store. A filter panel, expanded table row, selected tab or modal state often has exactly one consumer: the component rendering it. Moving that state into a service or store before another consumer exists adds architecture without solving a real sharing problem.', 'That is why I start Angular state management with the smallest primitive that solves the current problem: a local signal. State moves outward only when the application proves that it needs to be shared.', { type: 'heading', text: 'When Angular Signals are enough' }, { type: 'image', src: '/media/insights/angular-signals-state-management/observable-vs-signal-state.webp', alt: 'Observable-based Angular state spread across services and subscriptions compared with a single component signal.', width: 1586, height: 992, caption: 'The same toggle: several files and a subscription lifecycle on one side, one signal on the other.', }, 'Consider a filter panel whose open state is used by only one component. A service backed by a BehaviorSubject works, but it introduces another file, an observable, a subscription and teardown logic for a value that never leaves the component.', { type: 'code', language: 'typescript', caption: 'Local UI state can stay close to the component that owns it.', code: `export class FilterPanelComponent { readonly open = signal(false); toggle(): void { this.open.update((value) => !value); } }`, }, 'There is no subscription or teardown, and a developer reading the component can immediately see where the state originates. For component-specific UI state, that proximity is valuable.', { type: 'heading', text: 'The Angular state promotion rule' }, { type: 'image', src: '/media/insights/angular-signals-state-management/state-promotion-rule.webp', alt: 'Angular state promotion from a local component signal, to shared service signals, to an application store.', width: 1536, height: 1024, caption: 'State moves outward only when a second real consumer appears — not in anticipation of one.', }, 'The rule I use is simple: promote state only when a second real consumer appears. Do not design around a consumer that might exist next quarter. Wait until another component actually needs the same state.', 'The progression then becomes predictable: start with a signal inside the component, move shared signals and computed values into a service when multiple consumers appear, and introduce a store when the state becomes genuinely application-wide or workflow-driven.', { type: 'aside', text: 'Before adding a store, ask one question: can I name the second consumer and point to its file? If not, keep the state local.', }, { type: 'heading', text: 'When to move Signals into a service' }, 'A service becomes useful when multiple components need the same source of truth. Derived state can then live beside the source state as computed signals instead of being recreated independently by every consumer.', { type: 'code', language: 'typescript', caption: 'Shared Signals and computed state keep one definition for every consumer.', code: `@Injectable({ providedIn: 'root' }) export class CaseQueueState { private readonly cases = signal<Case[]>([]); readonly filter = signal<CaseFilter>('all'); readonly visibleCases = computed(() => { const filter = this.filter(); return filter === 'all' ? this.cases() : this.cases().filter( (caseItem) => caseItem.status === filter ); }); load(cases: Case[]): void { this.cases.set(cases); } }`, }, { type: 'heading', text: 'When Angular state actually needs a store' }, 'A store becomes more useful when state must survive navigation, multiple unrelated areas of the application can update it, complex workflows depend on predictable transitions, or the application benefits from centralized event-driven state management.', 'This is not an argument against NgRx or other Angular state-management libraries. They solve real problems. The important decision is whether the application currently has those problems.', { type: 'heading', text: 'Signals and zoneless Angular' }, { type: 'image', src: '/media/insights/angular-signals-state-management/signals-precise-updates.webp', alt: 'Angular components with no dependency on a changed signal staying untouched while dependent components update.', width: 1586, height: 992, caption: 'Under zoneless change detection, only the components that read the signal do any work.', }, 'Signals also fit naturally with zoneless Angular because state changes become explicit. Components depending on a signal can be notified when that signal changes instead of relying on broad asynchronous change-detection triggers.', { type: 'code', language: 'typescript', caption: 'Angular can run without Zone.js when application state changes are explicit.', code: `bootstrapApplication(AppComponent, { providers: [ provideZonelessChangeDetection(), ], });`, }, { type: 'heading', text: 'The state-management test I use' }, 'Before introducing another state-management layer, I ask: who owns this state, who reads it, who writes it, and does it need to survive the component or route that created it?', 'If there is one owner and one consumer, a component signal is usually enough. If several components need it, promote it to a service. If unrelated parts of the application coordinate through it or the workflow requires centralized transitions, then a store has earned its place.', 'Starting small is easier to reverse than starting with unnecessary architecture. Angular Signals make that progression inexpensive, which is why local state is now my default rather than something I optimize toward later.',], }, { id: 'angular-performance-core-web-vitals', cover: { src: '/media/insights/angular-performance-core-web-vitals/cover.webp', alt: 'Angular Core Web Vitals performance architecture showing loading, layout stability and interaction responsiveness.', width: 1730, height: 909, }, takeaways: ['Treat Angular performance as a product requirement instead of a separate optimization phase.', 'Prevent layout shift by reserving space before asynchronous content arrives.', 'Put performance budgets and loading expectations directly into feature requirements.', 'Use INP to identify main-thread work that makes Angular interfaces feel unresponsive.',], topic: 'Performance', seoTitle: 'Angular Performance Optimization with Core Web Vitals', seoDescription: 'Improve Angular Core Web Vitals by treating loading, INP, layout stability and API behaviour as product requirements instead of post-launch optimizations.', datePublished: '2026-09-12', number: '02', title: 'Angular Performance: Make Core Web Vitals a Product Requirement', dek: 'Angular performance is easier to protect while features are being built than to recover later. Treat loading, interaction delay and layout stability as part of the feature specification.', related: [{ label: 'Angular performance optimization', href: '/services/angular-performance-optimization', }, { label: 'Fiji Immigration internal system — the 40% API reduction', href: '/work/fiji-immigration-internal', }, { label: 'InsureMet — the dense table views', href: '/work/insuremet', }, { label: 'Angular codebase audit', href: '/insights/angular-codebase-audit', },], cta: 'If your Angular application feels slow but the team cannot identify whether the cause is network traffic, change detection, bundle size or rendering, start with measurement. I use scoped performance investigations to identify the actual bottleneck before changing the architecture.', body: ['The Fiji immigration internal management system ended up roughly 50% faster on the frontend, with about 40% less API consumption. Those improvements did not come from a dedicated performance sprint. They came from treating loading behaviour as part of the feature requirements while the application was being built.', 'That distinction matters because most frontend performance problems are inexpensive when they are created and expensive after they become architecture.', { type: 'heading', text: 'Why Angular performance cannot be a final optimization phase' }, 'When performance becomes a separate phase, it competes with feature work for schedule. Feature work usually wins because it has an immediate stakeholder and visible product output.', 'The larger problem is that performance issues compound. One component fetching reference data independently is harmless. Forty components following the same pattern can turn into duplicate API requests, network waterfalls and a caching problem that now requires architectural work.', { type: 'heading', text: 'Reduce duplicate Angular API requests before optimizing rendering' }, { type: 'image', src: '/media/insights/angular-performance-core-web-vitals/duplicate-vs-cached-requests.webp', alt: 'Duplicate Angular HTTP requests compared with one shared cached API request.', width: 1586, height: 992, }, 'On the immigration case-management screens, independently developed panels requested the same reference data when they initialized. Each component was reasonable in isolation, but together they produced five or six calls to identical endpoints during one navigation.', { type: 'code', language: 'typescript', caption: 'A component-level request is simple in isolation but becomes expensive when several panels repeat it.', code: `export class DocumentPanelComponent implements OnInit { countries: Country[] = []; documentTypes: DocumentType[] = []; constructor(private readonly api: ReferenceApi) {} ngOnInit(): void { this.api.countries().subscribe((countries) => { this.countries = countries; }); this.api.documentTypes().subscribe((types) => { this.documentTypes = types; }); } }`, }, 'Shared reference data belongs behind a shared data boundary. Using a cached RxJS stream allows multiple consumers to join the same request instead of independently starting new ones.', { type: 'code', language: 'typescript', caption: 'shareReplay allows multiple Angular consumers to reuse the same reference-data request.', code: `@Injectable({ providedIn: 'root' }) export class ReferenceDataService { private readonly cache = new Map<string, Observable<unknown>>(); private lookup<T>( key: string, fetch: () => Observable<T> ): Observable<T> { if (!this.cache.has(key)) { this.cache.set( key, fetch().pipe( shareReplay({ bufferSize: 1, refCount: false, }) ) ); } return this.cache.get(key) as Observable<T>; } }`, }, { type: 'heading', text: 'Prevent Cumulative Layout Shift at implementation time' }, { type: 'image', src: '/media/insights/angular-performance-core-web-vitals/layout-stability-cls.webp', alt: 'Comparison of unstable and stable layouts demonstrating how reserved space prevents cumulative layout shift.', width: 1586, height: 992, }, 'Cumulative Layout Shift has the same pattern. It rarely comes from one major mistake. It accumulates from images without dimensions, asynchronous sections that collapse before content arrives, and banners inserted above existing content.', { type: 'code', language: 'html', caption: 'Reserve the final layout before asynchronous content arrives.', code: `<img [src]="applicant.photoUrl" alt="" width="240" height="320" /> <div class="panel" style="min-height: 18rem"> @if (documents(); as docs) { <app-document-list [documents]="docs" /> } @else { <app-skeleton-rows [count]="4" /> } </div>`, }, { type: 'heading', text: 'Put performance requirements into the feature specification' }, 'A feature specification can state how many requests a route may perform on initial load, which data should come from a parent or resolver, whether image space must be reserved and what immediate feedback should appear after an interaction.', { type: 'aside', text: 'Performance requirements work best when they live beside functional requirements. When they live in a future optimization backlog, they are much easier to postpone.', }, { type: 'heading', text: 'Improve Angular INP by protecting the main thread' }, { type: 'image', src: '/media/insights/angular-performance-core-web-vitals/interaction-responsiveness-inp.webp', alt: 'Interaction timelines comparing blocking work with immediate UI feedback before expensive Angular processing.', width: 1586, height: 992, }, 'Interaction to Next Paint exposes a different category of performance problem. A click can technically complete quickly while still feeling broken if synchronous work prevents the browser from painting feedback.', 'For dense data views, acknowledge the interaction first and then perform expensive work. For genuinely heavy computation, move the work to a worker or reduce the amount processed in one frame.', { type: 'heading', text: 'Measure the Angular bottleneck before fixing it' }, 'Angular performance problems usually fall into several different categories: network waterfalls and duplicate requests, unnecessary change detection, oversized initial bundles, or expensive rendering. They can all appear to the user as the same complaint: the page feels slow.', 'The fix for one category does not necessarily improve another. Measurement is therefore not a final verification step. It is the first step in deciding what work should happen at all.',], }, { id: 'enterprise-ui-design-restraint', cover: { src: '/media/insights/enterprise-ui-design-restraint/cover.webp', alt: 'Enterprise UI design showing restrained dashboard layouts, clear hierarchy and minimal visual noise.', width: 1730, height: 909, }, takeaways: ['Design enterprise software for repeated daily use rather than first-impression novelty.', 'Use motion only when it communicates hierarchy, location or state.', 'Give one accent colour one consistent semantic purpose across the product.', 'Reduced motion, touch targets and interface density are part of the same restraint principle.',], topic: 'Design', seoTitle: 'Enterprise UI Design Principles for Complex Applications', seoDescription: 'Practical enterprise UI design principles for complex applications: restrained motion, clear hierarchy, consistent accent colour, accessibility and usable interface density.', datePublished: '2026-09-12', number: '03', title: 'Enterprise UI Design: Why Quiet Interfaces Age Better', dek: 'Enterprise interfaces are used repeatedly, often for years. Restraint in motion, colour, density and hierarchy makes complex software easier to understand and maintain.', related: [{ label: 'Ionic and cross-platform mobile services', href: '/services/ionic-development', }, { label: 'VNPF blo mi member app', href: '/work/vnpf-blo-mi', }, { label: 'Angular UI component architecture', href: '/work/ui-component-architecture', }, { label: 'Ionic offline-first architecture', href: '/insights/ionic-offline-first-architecture', },], cta: 'If an enterprise product looked polished at launch but now feels visually noisy, inconsistent or tiring to use, the problem is often the interface system rather than an individual screen. I help teams simplify those systems without redesigning everything from scratch.', body: ['The enterprise interfaces I have seen age best are rarely the ones with the most animation, decoration or visual variety. They are the ones where hierarchy is obvious, interactions are predictable and the interface gets out of the way after the user understands it.', 'That matters because enterprise software is not experienced once. An immigration officer may work through the same case-management interface hundreds of times a week. A pension member may open an app repeatedly for one specific piece of information. The repeated experience is the real product.', { type: 'heading', text: 'Design enterprise UI for the fortieth use' }, 'Animation that feels polished during a design review can feel like latency after repeated daily use. This does not mean enterprise applications should have no motion. It means motion needs a job.', { type: 'heading', text: 'Use UI motion only when it communicates information' }, { type: 'image', src: '/media/insights/enterprise-ui-design-restraint/decoration-vs-spatial-meaning.webp', alt: 'Enterprise dashboards comparing decorative animation with functional motion that explains interface structure.', width: 1586, height: 992, }, 'A panel sliding from the edge it will return to communicates spatial information. It tells the user where the panel came from and supports the mental model for dismissing it. A card fading upward simply because every card fades upward communicates much less.', { type: 'aside', text: 'Turn the animation off and read the interface. If the hierarchy collapses, the layout is relying on motion to explain something the static design should already communicate.', }, { type: 'heading', text: 'Give your enterprise UI accent colour one job' }, { type: 'image', src: '/media/insights/enterprise-ui-design-restraint/one-accent-colour.webp', alt: 'Restrained enterprise dashboard using a single accent colour to identify the primary next action.', width: 1586, height: 992, }, 'A consistent accent colour can become part of the product language. If it always identifies the next meaningful action, users learn that relationship quickly and carry it across screens.', 'The system becomes weaker when the same accent is also used for decorative headings, arbitrary emphasis and unrelated status information. Consistency reduces the amount of interpretation each new screen requires.', { type: 'code', language: 'css', caption: 'A small design-token system is easier for future developers to understand and preserve.', code: `:root { --color-accent: oklch(0.72 0.17 48); --duration-ui: 160ms; --duration-section: 420ms; --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1); }`, }, { type: 'heading', text: 'Treat reduced motion as part of the default design' }, { type: 'image', src: '/media/insights/enterprise-ui-design-restraint/reduced-motion-and-touch-targets.webp', alt: 'Reduced-motion enterprise layouts and accessible mobile controls preserving hierarchy and usability.', width: 1586, height: 992, }, 'The interface should remain understandable when animation is unavailable. Reduced-motion preferences, older devices and constrained rendering environments all make that a practical requirement rather than an edge case.', { type: 'code', language: 'css', caption: 'Make the static interface correct first, then add motion as an enhancement.', code: `.panel { transform: none; opacity: 1; } @media (prefers-reduced-motion: no-preference) { .panel { animation: panel-in var(--duration-section) var(--ease-out-expo); } }`, }, { type: 'heading', text: 'Enterprise mobile UI needs usable density' }, 'Restraint matters on mobile for a different reason: every decorative element consumes space that could have belonged to something the user needs to press, read or understand.', { type: 'code', language: 'css', caption: 'Keep interactive controls large enough for touch without making every visual element oversized.', code: `.control { min-height: 44px; min-width: 44px; display: inline-flex; align-items: center; justify-content: center; } @media (pointer: coarse) { .control { min-height: 48px; min-width: 48px; } }`, }, { type: 'heading', text: 'Why restrained enterprise interfaces are easier to maintain' }, 'The long-term advantage is not only visual. A restrained system has fewer arbitrary decisions. A new developer can infer a product with one accent rule, a small spacing system and three motion durations by inspecting a few screens.', 'When every screen introduces new colours, timings and interaction patterns, the interface system exists only in the memory of the people who originally built it. Restraint makes the product easier for users to learn and easier for future teams to maintain.',], }, { id: 'angular-zoneless-change-detection', cover: { src: '/media/insights/angular-zoneless-change-detection/cover.webp', alt: 'Zone.js global change detection compared with explicit Angular Signals updating only dependent components.', width: 1730, height: 909, }, takeaways: ['Migrate to zoneless Angular incrementally instead of creating a long-lived migration branch.', 'Audit timers, manual change detection and async callbacks before disabling Zone.js.', 'Convert notification boundaries to Signals while keeping RxJS for genuine stream problems.', 'Audit third-party libraries before enabling zoneless change detection in production.',], topic: 'Architecture', seoTitle: 'Angular Zoneless Change Detection: Practical Migration Guide', seoDescription: 'A practical Angular zoneless migration guide covering Signals, RxJS, timers, third-party libraries, Zone.js removal and incremental change detection migration.', datePublished: '2026-09-15', number: '04', title: 'Angular Zoneless Change Detection: A Practical Migration Guide', dek: 'Going zoneless is the final step, not the first. Make Angular state changes explicit, fix async boundaries and migrate incrementally before removing Zone.js.', related: [{ label: 'Angular Signals for state management', href: '/insights/angular-signals-state-management', }, { label: 'Angular development services', href: '/services/angular-development', }, { label: 'Zellavora AI Resume Builder — zoneless in production', href: '/work/zellavora-ai-resume-builder', },], cta: 'Planning a zoneless Angular migration while the application is still shipping features? I help teams audit Zone.js dependencies, sequence the migration and move toward explicit state updates without maintaining a risky long-lived branch.', body: ['Enabling zoneless change detection is one of the smallest parts of a zoneless Angular migration. The difficult part is finding the places where the application currently depends on Zone.js to notice that something changed.', 'The migration becomes much safer when zoneless is treated as a property the application earns rather than a flag that gets enabled first.', { type: 'heading', text: 'Why a big-bang Angular zoneless migration is risky' }, { type: 'image', src: '/media/insights/angular-zoneless-change-detection/zonejs-vs-signals-change-detection.webp', alt: 'Before and after comparison of Zone.js global change detection and explicit signal notification in Angular.', width: 1586, height: 992, caption: 'Zone.js checks the whole component tree; a signal notifies only the components that read it.', }, 'A long-lived migration branch quickly diverges from active feature development. Every feature merged into main creates another conflict with code that may already have been converted on the migration branch.', 'A safer approach is to make each preparation step independently useful and merge it directly into the application while Zone.js is still present.', { type: 'heading', text: 'Step 1: audit your Angular Zone.js dependencies' }, { type: 'code', language: 'bash', caption: 'Search for common places where Angular code may depend on implicit Zone.js change detection.', code: `rg -n "setTimeout|setInterval" src --type ts rg -n \ "NgZone|runOutsideAngular|ApplicationRef.tick" \ src --type ts rg -n \ "detectChanges|markForCheck|ChangeDetectorRef" \ src --type ts rg -n \ "addEventListener|new Worker|WebSocket|IntersectionObserver" \ src --type ts`, }, 'Classify the results instead of automatically replacing them. Some are state mutations that should become explicit signal writes. Some are legitimate work outside Angular. Others are manual change-detection calls that reveal an existing notification problem.', { type: 'heading', text: 'Step 2: convert change-detection triggers to Signals' }, 'The useful migration boundary is the source of the asynchronous state change rather than the component consuming it. Once a timer or callback writes to a signal, every consumer of that signal has an explicit notification mechanism.', { type: 'code', language: 'typescript', caption: 'A Signal makes the state update itself the notification.', code: `export class SessionBannerComponent { readonly remaining = signal(0); private readonly session = inject(SessionService); constructor() { const id = setInterval(() => { this.remaining.set( this.session.secondsLeft() ); }, 1000); inject(DestroyRef).onDestroy(() => { clearInterval(id); }); } }`, }, { type: 'aside', text: 'This work is useful even before Zone.js is removed. Explicit Signal updates create more precise state boundaries in a normal Angular application too.', }, { type: 'heading', text: 'Step 3: handle the Angular RxJS boundary correctly' }, { type: 'image', src: '/media/insights/angular-zoneless-change-detection/rxjs-to-signal-boundary.webp', alt: 'Angular async sources flowing through an RxJS pipeline and converting to signals at an explicit toSignal boundary.', width: 1586, height: 992, caption: 'RxJS stays where the problem is a stream; toSignal marks the single boundary where it becomes template state.', }, 'Zoneless Angular does not mean removing RxJS. Search debouncing, cancellation, WebSockets and merged asynchronous sources are still stream problems.', 'The important distinction is the boundary where an observable result becomes component state. Converting that boundary to a signal makes the notification explicit.', { type: 'code', language: 'typescript', caption: 'Use toSignal when an RxJS stream becomes state consumed by the Angular template.', code: `export class CaseListComponent { private readonly api = inject(CaseApi); readonly cases = toSignal( this.api.cases(), { initialValue: [] as Case[], } ); }`, }, { type: 'heading', text: 'Step 4: audit third-party Angular libraries' }, 'Third-party libraries often determine the real migration timeline. Charting libraries, map SDKs, older UI components and browser integrations may invoke callbacks outside Angular.', 'At those boundaries, update application state explicitly rather than depending on the zone to observe the callback.', { type: 'code', language: 'typescript', caption: 'A Signal write makes a third-party callback visible to Angular without Zone.js.', code: `export class ChartHostComponent { readonly selectedPoint = signal<Point | null>(null); private init(el: HTMLElement): void { thirdPartyChart(el, { onSelect: (point: Point) => { this.selectedPoint.set(point); }, }); } }`, }, { type: 'heading', text: 'Step 5: enable Angular zoneless change detection' }, { type: 'image', src: '/media/insights/angular-zoneless-change-detection/incremental-zoneless-migration.webp', alt: 'A five-step incremental Angular zoneless migration: audit, signals, RxJS boundary, library audit, then zoneless.', width: 1536, height: 1024, caption: 'Each step is useful on its own and can merge into main while Zone.js is still enabled.', }, 'Once application state changes are explicit and third-party boundaries have been audited, enabling zoneless change detection becomes the final verification step rather than the beginning of the migration.', { type: 'code', language: 'typescript', caption: 'Enable zoneless change detection after the application has been prepared for it.', code: `bootstrapApplication(AppComponent, { providers: [ provideZonelessChangeDetection(), provideBrowserGlobalErrorListeners(), ], });`, }, 'Remove Zone.js from both application and test polyfills. Keeping it in the test environment can hide exactly the notification problems the migration is intended to expose.', { type: 'heading', text: 'The real benefit of zoneless Angular' }, 'The strongest reason to migrate is not a single benchmark. Zoneless architecture encourages precise state ownership and explicit notification boundaries.', 'Most of that architectural value appears before Zone.js is removed. If each migration step improves the running application independently, the project remains safe to pause, ship and continue without a branch that becomes increasingly difficult to merge.',], }, { id: 'ionic-offline-first-architecture', cover: { src: '/media/insights/ionic-offline-first-architecture/cover.webp', alt: 'Ionic offline-first architecture with a local data layer, sync engine and pending sync queue against a remote API.', width: 1731, height: 909, }, takeaways: ['Model fresh, stale and unavailable data instead of treating connectivity as a simple online/offline boolean.', 'Choose Capacitor storage based on the consequence of losing or exposing the data.', 'Use idempotency keys for queued offline mutations so retries cannot create duplicate records.', 'Tell users clearly whether an action was accepted, queued or rejected.',], topic: 'Mobile', seoTitle: 'Ionic Offline-First Architecture with Angular and Capacitor', seoDescription: 'Build offline-first Ionic apps with Angular and Capacitor using cached data, SQLite, secure storage, queued mutations, idempotency keys and honest offline UX.', datePublished: '2026-09-16', number: '05', title: 'Ionic Offline-First Architecture with Angular & Capacitor', dek: 'Reliable mobile apps need more than an offline error message. Cache useful data, preserve its age, queue safe mutations and tell users exactly what happened.', related: [{ label: 'Ionic and cross-platform mobile services', href: '/services/ionic-development', }, { label: 'VNPF blo mi member app', href: '/work/vnpf-blo-mi', }, { label: 'Enterprise UI design principles', href: '/insights/enterprise-ui-design-restraint', },], cta: 'Building an Ionic member, field or service application for users with unreliable connectivity? Define the offline data and mutation model before designing the screens. I help teams establish that architecture early so offline support does not become a rewrite later.', body: ['The VNPF member application was built for provident-fund members in Vanuatu using the phones and networks available to them. That environment makes connectivity part of the architecture rather than an error case.', 'An offline-first Ionic application therefore needs to answer more than whether the device currently has a network connection. It needs to know what data is available, how old that data is and what happens when the user performs an action that cannot yet reach the server.', { type: 'heading', text: 'Model fresh, stale and unavailable data' }, { type: 'image', src: '/media/insights/ionic-offline-first-architecture/network-first-vs-offline-first.webp', alt: 'Network-first Ionic app blocked by a failed request compared with an offline-first app reading from a local database.', width: 1586, height: 992, caption: 'In a network-first app the connection is a dependency; in an offline-first app it is only what synchronisation needs.', }, 'For read operations, three states are more useful than online and offline: fresh data, cached data with a known age, and no available data.', { type: 'code', language: 'typescript', caption: 'Store the fetch timestamp beside cached data so the UI can represent freshness honestly.', code: `export interface Cached<T> { value: T; fetchedAt: number; } @Injectable({ providedIn: 'root' }) export class BalanceStore { private readonly cached = signal<Cached<Balance> | null>(null); readonly balance = computed( () => this.cached()?.value ?? null ); readonly freshness = computed(() => { const entry = this.cached(); if (!entry) { return 'none' as const; } const age = Date.now() - entry.fetchedAt; return age < 5 * 60_000 ? ('fresh' as const) : ('stale' as const); }); }`, }, 'A stale balance can still be useful when its age is visible. Hiding cached information behind an indefinite loading state often produces a worse experience than showing the last known value honestly.', { type: 'code', language: 'html', caption: 'Keep cached data useful while clearly communicating that it is not current.', code: `@switch (freshness()) { @case ('fresh') { <app-balance [value]="balance()" /> } @case ('stale') { <app-balance [value]="balance()" /> <p class="note"> Showing saved data from {{ updatedAt() | date: 'short' }} </p> } @case ('none') { <app-empty-state message="Your balance will appear here once you are back online." /> } }`, }, { type: 'heading', text: 'Choose Capacitor storage based on the data' }, 'Not every local-storage option has the same purpose. Small UI preferences can live in a key-value store. Queryable offline records fit a database such as SQLite. Authentication credentials belong in platform-backed secure storage.', { type: 'code', language: 'typescript', caption: 'Use different storage mechanisms for credentials, structured offline data and disposable UI preferences.', code: `await SecureStoragePlugin.set({ key: 'refresh_token', value: token, }); await db.run( \`INSERT OR REPLACE INTO statements (id, period, payload) VALUES (?, ?, ?)\`, [ statement.id, statement.period, JSON.stringify(statement), ] ); await Preferences.set({ key: 'last_tab', value: 'balance', });`, }, { type: 'heading', text: 'Queue offline writes with idempotency keys' }, { type: 'image', src: '/media/insights/ionic-offline-first-architecture/offline-write-queue.webp', alt: 'Ionic offline write queue: save locally, queue while offline, then sync in the background when connectivity returns.', width: 1536, height: 1024, caption: 'The write succeeds locally first, so the queue — not the user — carries the retry.', }, 'Offline reads are relatively straightforward. Offline writes are harder because a failed response does not prove that the server never received the request.', 'Generate an idempotency key when the user performs the action and reuse that key on every retry. The server can then recognize repeated delivery of the same mutation instead of creating another record.', { type: 'code', language: 'typescript', caption: 'Generate the mutation identity once and preserve it for every retry.', code: `async submit( claim: ClaimDraft ): Promise<void> { const action: QueuedAction = { key: crypto.randomUUID(), kind: 'claim.submit', payload: claim, queuedAt: Date.now(), }; await this.queue.add(action); void this.flush(); }`, }, { type: 'aside', text: 'If queued operations depend on order, stop processing after a transient failure instead of skipping ahead and producing an application state that never existed on the client.', }, { type: 'heading', text: 'Design the offline status message as part of the workflow' }, { type: 'image', src: '/media/insights/ionic-offline-first-architecture/reconnection-and-conflict-resolution.webp', alt: 'Offline-first reconnection flow showing successful sync, retry after temporary failure, and conflict resolution options.', width: 1536, height: 1024, caption: 'Reconnection has three outcomes, and each one needs a message the user can act on.', }, 'A user action can be accepted by the server, saved locally for later submission or rejected. Those outcomes have different consequences and should not share the same generic error message.', 'A queued action should explain that the work has been saved on the device and what will happen when connectivity returns. That gives the user confidence that pressing the button repeatedly is unnecessary.', { type: 'heading', text: 'Why offline-first architecture must be decided early' }, 'Offline support changes the data layer: where values come from, whether they have an age, how mutations are represented and what retry means. Retrofitting those concepts after every feature assumes permanent connectivity can approach a rewrite.', 'Designing those boundaries at the beginning is comparatively inexpensive. That is why offline behaviour belongs in the product and architecture specification rather than a later resilience backlog.',], }, { id: 'accessible-angular-forms', cover: { src: '/media/insights/accessible-angular-forms/cover.webp', alt: 'Accessible Angular form field with a label, hint and error message wired together with aria-invalid and aria-describedby.', width: 1731, height: 909, }, takeaways: ['Preserve form data so validation, navigation or session failure never destroys completed work.', 'Make errors announced, programmatically associated and easy to navigate.', 'Write validation messages as instructions that tell the user how to recover.', 'Give multi-step Angular forms a clear current position and remaining journey.',], topic: 'Accessibility', seoTitle: 'Accessible Angular Forms: Validation, Errors & Recovery', seoDescription: 'Build accessible Angular forms with clear validation, ARIA error associations, error summaries, focus management, draft recovery and usable multi-step form patterns.', datePublished: '2026-09-16', number: '06', title: 'Accessible Angular Forms: Validation, Errors & Recovery', dek: 'When a failed form costs users real time or opportunity, accessibility and recovery cannot be optional. Preserve input, make errors findable and explain exactly how to continue.', related: [{ label: 'Fiji Immigration Citizen Portal', href: '/work/fiji-immigration-external', }, { label: 'PRIMS Member Portal', href: '/work/prims-member-portal', }, { label: 'Frontend architecture services', href: '/services/frontend-architecture', },], cta: 'If you are building an Angular application, claim or onboarding flow where users cannot afford to lose their progress, the validation and recovery paths deserve the same engineering attention as successful submission. I help teams design and implement those flows accessibly.', body: ['Many form examples assume that failure costs the user very little. That assumption changes when the form is an immigration application, pension claim or another process the person is required to complete.', 'In those workflows, preserving progress, explaining errors and helping users recover are part of the core functionality rather than optional usability improvements.', { type: 'heading', text: 'Never lose the user’s Angular form data' }, 'A validation failure should not clear valid fields. Navigation should not silently destroy completed steps. A security-driven session timeout should not automatically mean that the user loses the work they already entered.', 'Persist drafts at meaningful points and restore them when the user returns. The exact persistence mechanism depends on the sensitivity of the data, but recovery should be designed before the failure happens.', { type: 'aside', text: 'Security requirements and draft recovery are separate concerns. A session may need to expire while the product still provides an appropriate, secure way to preserve recoverable work.', }, { type: 'heading', text: 'Make Angular validation errors findable' }, { type: 'image', src: '/media/insights/accessible-angular-forms/accessible-validation-messages.webp', alt: 'Validation shown only as a red border compared with an accessible error message announced to assistive technology.', width: 1586, height: 992, caption: 'A red border is invisible to a screen reader; the accessibility tree has to carry the same information.', }, 'A red border alone is not an accessible validation strategy. On a long form, the invalid control may be outside the viewport. Colour alone also does not provide enough information to assistive technology.', 'A robust error experience combines field-level associations, clear text, an error summary for larger forms and intentional focus management after submission.', { type: 'code', language: 'html', caption: 'Associate the input with both its hint and validation message and expose invalid state programmatically.', code: `<label for="passport-number"> Passport number </label> <input id="passport-number" [attr.aria-invalid]=" hasError('passportNumber') " [attr.aria-describedby]=" hasError('passportNumber') ? 'passport-number-error' : 'passport-number-hint' " /> <p id="passport-number-hint"> As printed on the photo page, without spaces. </p> @if (hasError('passportNumber')) { <p id="passport-number-error"> Enter your passport number. Use 7 to 9 letters or numbers. </p> }`, }, { type: 'heading', text: 'Use an accessible form error summary' }, { type: 'image', src: '/media/insights/accessible-angular-forms/error-summary-focus-management.webp', alt: 'Angular form error summary listing three problems, each linking to the field that needs correcting, with focus management.', width: 1536, height: 1024, caption: 'Focus moves to the summary, the summary links to the field, and the user never has to hunt for the error.', }, { type: 'code', language: 'html', caption: 'An error summary gives users a navigable overview when several fields fail validation.', code: `<div role="alert" tabindex="-1" #errorSummary > <h2> There are {{ errors().length }} problems with this application </h2> <ul> @for ( error of errors(); track error.field ) { <li> <a [href]="'#' + error.field"> {{ error.message }} </a> </li> } </ul> </div>`, }, { type: 'heading', text: 'Write Angular validation messages as instructions' }, 'Messages such as “Invalid format” describe the system. They do not tell the person how to continue. A useful message explains the expected value and the action required to correct it.', 'Hints should also appear before failure when a format is easy to misunderstand. Preventing an error is usually better than improving the message shown afterwards.', { type: 'heading', text: 'Choose validation timing carefully' }, 'Not every validation rule needs to run visibly on every keystroke. Showing an error while someone is still entering a perfectly valid value creates unnecessary noise.', 'Use timing that matches the rule and interaction. Format errors often make more sense after the field has been interacted with or when the user attempts to continue.', { type: 'heading', text: 'Make multi-step Angular forms announce position' }, { type: 'image', src: '/media/insights/accessible-angular-forms/multi-step-form-draft-recovery.webp', alt: 'Multi-step Angular form with step indicators and a restored draft after an expired session.', width: 1536, height: 1024, caption: 'The step indicator answers “where am I?” and the saved draft answers “can I safely come back?”.', }, 'Long forms are often easier to complete when divided into meaningful steps, but users need to know where they are and how much remains.', { type: 'code', language: 'html', caption: 'Expose the current step in both navigation and the page heading.', code: `<nav aria-label="Application progress"> <ol> @for ( step of steps; track step.id; let i = $index ) { <li [attr.aria-current]=" i === current() ? 'step' : null " > {{ i + 1 }}. {{ step.label }} </li> } </ol> </nav> <h1 tabindex="-1" #stepHeading> Step {{ current() + 1 }} of {{ steps.length }}: {{ steps[current()].label }} </h1>`, }, 'When a step changes, move focus to an appropriate heading or other meaningful location so keyboard and assistive-technology users receive the same transition that sighted users see visually.', { type: 'heading', text: 'Design form failure with the same care as success' }, 'Accessibility improvements in high-consequence forms usually improve the experience for everyone. Draft recovery helps interrupted users. Error summaries help anyone dealing with several invalid fields. Clear hints help first-time users understand unfamiliar formats.', 'The amount of recovery design should reflect the consequence of failure. The more expensive it is for a person to restart, the more important it becomes to preserve their work and make the path back to success obvious.',], }, { id: 'angular-codebase-audit', cover: { src: '/media/insights/angular-codebase-audit/cover.webp', alt: 'Angular codebase audit combining runtime behaviour, architecture, Git history, network and bundle evidence into a prioritized plan.', width: 1731, height: 909, }, takeaways: ['Run and profile an unfamiliar Angular application before forming opinions from the source code.', 'Measure codebase size, coupling, state patterns and change frequency before proposing architecture changes.', 'Use Git history and recent production failures to identify the areas creating real maintenance cost.', 'Separate network, change-detection, bundle and rendering problems before optimizing performance.',], topic: 'Practice', seoTitle: 'Angular Codebase Audit: A Practical Step-by-Step Guide', seoDescription: 'A practical Angular codebase audit covering architecture, Signals, RxJS, Git history, performance, change detection, bundle analysis and technical-debt prioritization.', datePublished: '2026-09-16', number: '07', title: 'How I Audit an Existing Angular Codebase', dek: 'Before refactoring an inherited Angular application, understand where its real cost lives. Measure the application, architecture, history and runtime behaviour before proposing changes.', related: [{ label: 'Angular development services', href: '/services/angular-development', }, { label: 'Angular performance with Core Web Vitals', href: '/insights/angular-performance-core-web-vitals', }, { label: 'Angular Signals state management', href: '/insights/angular-signals-state-management', },], cta: 'Inherited an Angular application that works but has become increasingly expensive to change? I run scoped codebase assessments that turn runtime behaviour, architecture and technical debt into a prioritized plan your team can execute with or without me.', body: ['Most inherited Angular applications arrive with a symptom: the application feels slow, features take too long to build, one area is difficult to change, or the team believes the architecture needs modernization.', 'The expensive mistake is treating the reported symptom as the diagnosis. Before recommending a rewrite, state-management change or Angular upgrade, I first establish where the actual cost is.', { type: 'heading', text: 'Step 1: run the Angular application before reading the code' }, { type: 'image', src: '/media/insights/angular-codebase-audit/symptom-vs-diagnosis.webp', alt: 'A slow Angular application split into network, change detection, bundle and rendering evidence rather than guessed fixes.', width: 1586, height: 992, caption: '“The app feels slow” is a symptom. Measuring each category first is what turns it into a diagnosis.', }, 'Use the product like a user before opening the architecture. Test representative workflows on realistic hardware and network conditions while keeping browser performance and network tools visible.', 'This quickly exposes repeated requests, delayed interactions, unexpected layout shifts and workflow friction that developers working in the application every day may have learned to ignore.', { type: 'heading', text: 'Step 2: measure the shape of the Angular codebase' }, 'Early auditing should focus on structural facts rather than subjective quality judgments.', { type: 'code', language: 'bash', caption: 'A small set of searches can quickly map Angular architecture and state-management patterns.', code: `# NgModules and standalone components rg -c "@NgModule" src --type ts rg -c "standalone: true" src --type ts # RxJS state and Signals rg -n \ "BehaviorSubject|new Subject" \ src --type ts rg -n \ "signal\\(|computed\\(" \ src --type ts # Store usage rg -l \ "StoreModule|createReducer|createEffect" \ src --type ts # Manual change detection rg -n \ "detectChanges\\(\\)" \ src --type ts`, }, 'These numbers do not tell you whether the code is good or bad. They tell you where architectural decisions live and which areas deserve closer inspection.', { type: 'heading', text: 'Step 3: use Git history to find expensive Angular files' }, { type: 'image', src: '/media/insights/angular-codebase-audit/codebase-structure-and-git-history.webp', alt: 'Angular codebase structure and architectural patterns beside Git change frequency and hotspot analysis per file.', width: 1536, height: 1024, caption: 'Complexity only costs you where the file also changes often — that intersection is the hotspot.', }, 'A complicated file that has not changed for two years may create less practical cost than a moderately complicated component modified in almost every release.', { type: 'code', language: 'bash', caption: 'Find Angular files that change most frequently and compare that with size and complexity.', code: `git log \ --since="1 year ago" \ --name-only \ --pretty=format: \ | rg "^src/.*\\.(ts|html)$" \ | sort \ | uniq -c \ | sort -rn \ | head -25`, }, { type: 'aside', text: 'Large, frequently changed and poorly tested files deserve attention because they combine architectural risk with real ongoing development cost.', }, { type: 'heading', text: 'Step 4: ask the team what broke recently' }, 'Production history is another architectural signal. Ask what last failed in production, which recent change took much longer than expected and which area developers avoid touching.', 'Those answers often reveal coupling and ownership problems that static analysis cannot show.', { type: 'heading', text: 'Step 5: separate Angular performance problems' }, 'Do not treat “the application is slow” as one category. Network duplication, change detection, initial bundle cost and rendering pressure need different evidence and different fixes.', { type: 'code', language: 'bash', caption: 'Use production build statistics and profiling tools to eliminate performance causes systematically.', code: `ng build \ --configuration production \ --stats-json npx source-map-explorer \ dist/**/*.js rg -L \ "ChangeDetectionStrategy.OnPush" \ src \ --type ts \ -g "*.component.ts"`, }, 'Then inspect the network waterfall for duplicate and unnecessarily serial requests. A performance recommendation should name the bottleneck rather than simply list every optimization Angular supports.', { type: 'heading', text: 'Turn the Angular audit into a prioritized plan' }, { type: 'image', src: '/media/insights/angular-codebase-audit/evidence-to-prioritized-plan.webp', alt: 'Angular audit findings scored by cost, risk, change frequency and effort, then split into act now, plan and leave alone.', width: 1536, height: 1024, caption: 'The output is not a list of everything imperfect, but an ordered list of what is worth changing next.', }, 'The useful output of an audit is a written plan. Each finding should explain what is happening, what it costs today, what changing it requires, what dependencies exist and approximately how large the work is.', 'A good audit should also identify code that looks imperfect but is not worth changing. Technical debt only deserves priority when it creates measurable risk, performance cost or development friction.', 'The final test is whether the team can act on the report without the person who wrote it. If the recommendations are specific, evidence-based and ordered correctly, the assessment remains useful even if another developer performs the implementation.',], }, { id: 'rxjs-reduce-api-calls', cover: { src: '/media/insights/rxjs-reduce-api-calls/cover.webp', alt: 'Angular panels sharing one cached RxJS stream instead of making duplicate HTTP API requests.', width: 1730, height: 909, }, takeaways: ['Duplicate Angular HTTP requests can emerge even when every component looks correct in isolation.', 'Use a shared RxJS stream with shareReplay to reuse stable reference-data requests.', 'Choose refCount deliberately because it controls whether cached streams survive after subscribers leave.', 'Design cache invalidation around events that change the data rather than arbitrary timers.',], topic: 'Performance', seoTitle: 'RxJS Angular API Optimization: Reduce Duplicate HTTP Requests', seoDescription: 'Learn how RxJS shareReplay can reduce duplicate Angular HTTP requests, how refCount affects caching and how to design reliable cache invalidation.', datePublished: '2026-09-12', number: '08', title: 'How RxJS Reduced Our Angular API Calls by 40%', dek: 'One enterprise Angular screen requested the same reference data five times. A shared RxJS caching layer removed the duplication without rewriting the consuming components.', related: [{ label: 'Angular performance optimization', href: '/services/angular-performance-optimization', }, { label: 'Fiji Immigration internal system — where this was measured', href: '/work/fiji-immigration-internal', }, { label: 'Angular performance with Core Web Vitals', href: '/insights/angular-performance-core-web-vitals', }, { label: 'Angular Signals state management', href: '/insights/angular-signals-state-management', },], cta: 'Seeing the same Angular endpoint multiple times during one navigation? The API may not be the bottleneck at all. I help teams trace duplicate requests, RxJS subscription behaviour and data ownership before changing backend or rendering code.', body: ['The original complaint on the Fiji immigration internal case-management system was simple: case pages felt slow. The initial assumption was that rendering or bundle size was responsible.', 'The network tab showed something different. Several stable reference endpoints — including country lists and workflow categories — were requested five or six times during one navigation.', { type: 'heading', text: 'Why duplicate Angular API requests happen' }, { type: 'image', src: '/media/insights/rxjs-reduce-api-calls/duplicate-reference-data-requests.webp', alt: 'Multiple Angular panels independently requesting identical reference API data.', width: 1586, height: 992, }, 'Each panel had been designed to be self-contained. It requested the data it needed during initialization instead of assuming that a parent component had already loaded it.', 'That is a reasonable component design in isolation. The problem appears when several independently reusable components need the same stable reference data.', { type: 'code', language: 'typescript', caption: 'A harmless request pattern becomes expensive when several components repeat it on the same screen.', code: `export class DocumentChecklistComponent implements OnInit { countries: Country[] = []; constructor( private readonly api: ReferenceApi ) {} ngOnInit(): void { this.api .getCountries() .subscribe((countries) => { this.countries = countries; }); } }`, }, { type: 'heading', text: 'Use RxJS shareReplay to share one HTTP request' }, { type: 'image', src: '/media/insights/rxjs-reduce-api-calls/sharereplay-one-request.webp', alt: 'Multiple RxJS subscribers sharing one Angular HTTP request through shareReplay.', width: 1586, height: 992, }, 'Moving every request into the parent would reduce duplication, but it would also make reusable panels dependent on a specific screen structure. A shared service can solve the request problem without changing those component boundaries.', { type: 'code', language: 'typescript', caption: 'shareReplay allows every subscriber to reuse the same Angular HTTP result.', code: `@Injectable({ providedIn: 'root' }) export class ReferenceApi { private readonly countries$ = this.http .get<Country[]>( '/api/reference/countries' ) .pipe( shareReplay({ bufferSize: 1, refCount: false, }) ); constructor( private readonly http: HttpClient ) {} getCountries(): Observable<Country[]> { return this.countries$; } }`, }, 'Multiple subscribers now share one HTTP request. Because the stream is created once at service level, returning to the screen can reuse the previously emitted value instead of automatically starting another request.', { type: 'aside', text: 'refCount is an architectural choice. refCount: false is useful for stable reference data you intentionally want to retain. More volatile or lifecycle-sensitive streams may require different behaviour.', }, { type: 'heading', text: 'RxJS caching is easy; cache invalidation is harder' }, { type: 'image', src: '/media/insights/rxjs-reduce-api-calls/event-driven-cache-invalidation.webp', alt: 'Event-driven RxJS cache invalidation clearing Angular reference data before the next request.', width: 1586, height: 992, }, 'Caching a value is only correct while that value remains valid. A country list may be effectively static for a session, while workflow categories or office locations may change after an administrative action.', 'Instead of choosing an arbitrary timeout, invalidate the cache when an event occurs that can actually make the cached value stale.', { type: 'code', language: 'typescript', caption: 'Invalidate cached RxJS data when the underlying resource changes.', code: `private countriesCache$?: Observable<Country[]>; getCountries(): Observable<Country[]> { this.countriesCache$ ??= this.http .get<Country[]>( '/api/reference/countries' ) .pipe( shareReplay({ bufferSize: 1, refCount: false, }) ); return this.countriesCache$; } invalidateCountries(): void { this.countriesCache$ = undefined; }`, }, { type: 'heading', text: 'The performance impact of removing duplicate requests' }, 'Across the case workflow, API consumption dropped by approximately 40%, while frontend load behaviour improved substantially. The important point is that the improvement came from changing the data layer rather than rewriting component rendering logic.', 'This is why the network tab is one of the first places I look when an Angular screen feels slow. Sort requests by URL and count duplicates before assuming the problem is rendering, change detection or the backend.', { type: 'heading', text: 'The RxJS lesson worth keeping' }, 'A duplicated HTTP request is often not a mistake in the component where it appears. It is evidence that several reasonable local decisions are composing into an expensive global behaviour.', 'Shared RxJS streams are useful because they let the data layer solve that composition problem while consumers keep simple boundaries. The important work is deciding what should be shared, how long it remains valid and what event makes it stale.',], }, { id: 'angular-performance-checklist', cover: { src: '/media/insights/angular-performance-checklist/cover.webp', alt: 'Angular performance checklist covering network, change detection, bundle, rendering and regression guards.', width: 1731, height: 909, }, takeaways: ['Reproduce Angular performance problems on realistic hardware and network conditions before optimizing.', 'Check duplicate requests before change detection, bundle size and rendering.', 'Use Angular DevTools and bundle analysis to identify evidence rather than applying optimizations globally.', 'Add budgets and automated checks so performance regressions do not return after the fix.',], topic: 'Performance', seoTitle: 'Angular Performance Optimization Checklist: Step-by-Step', seoDescription: 'Use this Angular performance optimization checklist in diagnostic order: network requests, change detection, bundle size, rendering and regression prevention.', datePublished: '2026-09-16', number: '09', title: 'Angular Performance Optimization Checklist — In the Right Order', dek: 'Angular performance work becomes much faster when you check the highest-probability causes first. Start with the network, then change detection, bundle cost and rendering.', related: [{ label: 'Angular performance optimization', href: '/services/angular-performance-optimization', }, { label: 'Reduce Angular API calls with RxJS', href: '/insights/rxjs-reduce-api-calls', }, { label: 'Angular performance with Core Web Vitals', href: '/insights/angular-performance-core-web-vitals', }, { label: 'Fiji Immigration internal system', href: '/work/fiji-immigration-internal', },], cta: 'Worked through the obvious Angular performance fixes but the application still feels slow? I run scoped performance investigations that identify the actual bottleneck and leave your team with a written, prioritized diagnosis.', body: ['Most Angular performance checklists are collections of possible optimizations. They tell you what can make an application slow but not which cause is worth investigating first.', 'I prefer a diagnostic order. Start with the causes that are fast to verify and frequently responsible, then move deeper only when the evidence requires it.', { type: 'heading', text: '0. Reproduce Angular performance on realistic hardware' }, 'Before changing code, reproduce the complaint on hardware and network conditions that resemble the environment where users experience it.', 'A fast development laptop on a local connection can hide network waterfalls, main-thread pressure and rendering costs that become obvious on a mid-range device.', { type: 'heading', text: '1. Check duplicate and serial Angular API requests' }, { type: 'image', src: '/media/insights/angular-performance-checklist/network-duplicate-and-serial-requests.webp', alt: 'Angular network panel showing duplicate requests to one endpoint and a serial request waterfall that could run in parallel.', width: 1586, height: 992, caption: 'Two different problems live in the same panel: the same request repeated, and requests that wait on each other for no reason.', }, 'Open the network panel, reload the route and sort requests by name. Identical endpoints appearing several times during one navigation are often the cheapest performance problem to identify and remove.', 'Then inspect the waterfall. Requests that execute sequentially even though they do not depend on each other unnecessarily extend the route loading time.', { type: 'heading', text: '2. Profile Angular change detection' }, { type: 'image', src: '/media/insights/angular-performance-checklist/change-detection-and-bundle-analysis.webp', alt: 'Angular DevTools change detection profile beside a production bundle split into initial load and lazy-loaded routes.', width: 1536, height: 1024, caption: 'Profile which components actually re-render, and check what the first route genuinely needs to download.', }, 'Use Angular DevTools to profile the interaction that feels slow. Look for components being checked repeatedly during interactions unrelated to them.', { type: 'code', language: 'bash', caption: 'A source search can identify candidates, but profiling should decide which components actually matter.', code: `rg -L \ "ChangeDetectionStrategy.OnPush" \ src \ --type ts \ -g "*.component.ts" \ | wc -l`, }, 'Do not automatically convert an entire application based on the count. A component becomes a performance concern when profiling shows that its checks are contributing to the interaction cost.', { type: 'heading', text: '3. Analyze the Angular production bundle' }, 'The useful question is not only whether the bundle is large. Ask what is inside the initial bundle and whether the first route actually needs those dependencies.', { type: 'code', language: 'bash', caption: 'Generate production statistics and inspect what is contributing to the initial Angular bundle.', code: `ng build \ --configuration production \ --stats-json npx source-map-explorer \ dist/**/*.js`, }, 'Look for large libraries imported for small features, entire icon packages, charting libraries loaded before their route and lazy routes accidentally made eager through another import.', { type: 'heading', text: '4. Inspect Angular rendering work' }, 'Once network, change detection and bundle cost have been investigated, inspect rendering. Large lists, expensive template expressions, unnecessary DOM nodes, missing identity tracking and layout instability can all increase interaction cost.', { type: 'aside', text: 'A function called directly from a template may execute repeatedly during change detection. Prefer derived state, pure pipes or precomputed values when the calculation is non-trivial or repeated across many rows.', }, { type: 'heading', text: '5. Prevent the Angular performance regression' }, { type: 'image', src: '/media/insights/angular-performance-checklist/rendering-profile-and-regression-guard.webp', alt: 'Angular rendering profile with a long task, the targeted fix, the verified result and the guards that prevent regression.', width: 1536, height: 1024, caption: 'Measure, fix the actual cause, verify the change, then add the guard that keeps it fixed.', }, 'A performance fix without a guard can disappear several releases later. Add the relevant protection after the cause is known: bundle budgets, automated performance checks, request-count expectations or field monitoring.', 'The guard should match the failure. A bundle budget will not protect against duplicate API calls, and a Lighthouse score alone will not explain a slow interaction inside a dense authenticated application.', { type: 'heading', text: 'Sometimes Angular is not the bottleneck' }, 'Profiling may show that the browser is mostly waiting for the backend. That is still a useful performance finding because it prevents a frontend team from spending weeks optimizing code that is not responsible for the delay.', 'The purpose of the checklist is not to perform every optimization. It is to eliminate possibilities in an order that reaches the actual bottleneck with the least wasted work.',], }, { id: 'ux-problem-approach', cover: { src: '/media/insights/ux-problem-approach/cover.webp', alt: 'UX process moving from user friction through understand, define, simplify, explore and validate to a clear experience.', width: 1731, height: 909, }, takeaways: ['Define the user problem before opening Figma or choosing a visual solution.', 'Map the complete user journey to find friction that individual screen reviews miss.', 'Simplify unnecessary decisions before adding new features or interface elements.', 'Explore multiple solutions and validate the assumption behind the design.',], topic: 'Design', seoTitle: 'UX Problem-Solving Process: My Product Design Approach', seoDescription: 'My UX problem-solving process as a product designer: define the problem, map journey friction, simplify flows, explore solutions, validate assumptions and iterate.', datePublished: '2026-09-13', number: '10', title: 'How I Approach UX Problems as a Product Designer', dek: 'A better-looking interface is not automatically a better experience. My UX process starts by understanding why something is difficult before deciding what should be designed.', related: [{ label: 'Enterprise UI design principles', href: '/insights/enterprise-ui-design-restraint', }, { label: 'Accessible Angular forms', href: '/insights/accessible-angular-forms', }, { label: 'Frontend architecture', href: '/services/frontend-architecture', }, { label: 'InsureMet — decisions made under time pressure', href: '/work/insuremet', },], cta: 'If users can technically complete your product flow but hesitate, abandon steps or repeatedly ask what to do next, the friction is usually identifiable. I run scoped UX reviews that map those problems and prioritize the changes with the highest practical impact.', body: ['When I encounter a frustrating product experience, my first instinct is not to redesign the screen. I start by asking why the task is difficult for the user.', 'The problem may be visual, but it may also be an unnecessary step, unclear information, too many decisions, weak hierarchy or a workflow asking the user to understand something the product could have handled for them.', 'That question — what can I make easier? — is the starting point for how I approach UX problems.', { type: 'heading', text: '1. Define the UX problem before opening Figma' }, 'Jumping directly into interface design makes it easy to improve the appearance of the wrong problem.', 'Consider a user searching for a 2BHK property. Hundreds of listings, overlapping filters, inconsistent pricing and several contact actions may initially look like a listing-card design problem.', 'The deeper problem could instead be helping someone confidently narrow hundreds of properties into a small set worth visiting. That framing changes the solution completely.', { type: 'heading', text: '2. Review the experience like a first-time user' }, 'Product teams gradually learn how their own interface works. New users do not have that context.', 'I look for moments where a person has to stop and interpret what the product expects. In a cab-booking flow, questions such as whether the pickup location is exact, whether the fare is final or whether the destination can still be changed all create small amounts of uncertainty.', 'When users repeatedly have to ask “what happens next?”, the interface is transferring work from the product to the person.', { type: 'heading', text: '3. Map the user journey and identify friction' }, 'Individual screens rarely explain the complete experience. I map the journey and pay particular attention to transitions between stages.', { type: 'image', src: '/media/insights/ux-problem-approach/journey-friction.webp', alt: 'E-commerce user journey from discovery to payment with friction points identified at each stage.', width: 1774, height: 887, caption: 'Looking at transitions reveals friction that is easy to miss when reviewing each screen independently.', }, 'For an e-commerce journey, that might mean discover → compare → select → add to cart → checkout → pay. The important questions live between those stages: whether the user has enough information to continue, whether costs appear too late and whether the next action is obvious.', { type: 'aside', text: 'UX friction compounds. A single small problem may not cause abandonment, but several small uncertainties across one journey can produce a measurable drop-off.', }, { type: 'heading', text: '4. Simplify the UX before adding features' }, 'Adding another feature is not always the best response to a usability problem. Sometimes the strongest design decision is removing a decision the user should not have needed to make.', { type: 'image', src: '/media/insights/ux-problem-approach/simplify-signup.webp', alt: 'Before-and-after signup flow showing a complex eight-field form simplified to essential account information.', width: 1536, height: 1024, caption: 'Ask for information when the product has a visible reason to need it, rather than collecting everything at the first step.', }, 'If account creation only requires an email and password, asking for phone number, company, job title, location and date of birth creates decisions before the user has received enough value to understand why those questions matter.', 'Before asking what should be added, I ask what can be removed, delayed or inferred.', { type: 'heading', text: '5. Use familiar UX patterns intentionally' }, 'Established interaction patterns reduce learning cost. A heart icon already communicates save or wishlist in many consumer products. Replacing it simply to make an interface feel unique gives users another convention to learn.', 'The goal is not to copy competitors. It is to understand which conventions already carry meaning and decide whether breaking them creates enough value to justify the learning cost.', { type: 'heading', text: '6. Explore multiple UX solutions' }, 'The first design idea is still an assumption. I prefer to explore several plausible approaches before investing heavily in one.', { type: 'image', src: '/media/insights/ux-problem-approach/explore-solutions.webp', alt: 'Three UX solutions for property comparison: improved cards, side-by-side comparison and a smarter shortlist.', width: 1536, height: 1024, caption: 'Compare solutions by how well they solve the user problem and how much complexity they introduce.', }, 'If users struggle to compare properties, possible solutions include improving card hierarchy, adding direct side-by-side comparison or making the shortlist more useful.', 'The decision should come from the problem, expected impact and implementation complexity rather than which mockup looks most impressive.', { type: 'heading', text: '7. Validate the assumption and iterate' }, 'A polished prototype can still solve the wrong problem. If a team assumes users cannot find relevant properties, it may improve filters. Research may instead reveal that users find listings easily but do not trust the information inside them.', 'Validation can come from usability testing, user conversations, analytics, support feedback or controlled experiments. The method changes by project; the purpose does not.', 'The process is closer to understand → explore → design → validate → learn → iterate than design → polish → finish.', { type: 'heading', text: 'Product design is a sequence of decisions' }, 'The longer I work on products, the more I see product design as decisions rather than screens: what information appears first, what can be removed, where someone is likely to hesitate, what they need before committing and what the product can decide on their behalf.', 'When I open Figma, I do not want the first question to be what can I design. I want it to be what can I make easier.',], },];